test("AC-1: 2 h 1 min stay rounds up to 3 billable hours", () => {
  const r = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-10 10:01" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 121, roundedHours: 3, billableHours: 3, flags: [] });
});
test("AC-2: day when clocks go forward (2026-03-08) bills 23 real hours, not 24", () => {
  const r = code.billableObservationHours({ admission: "2026-03-07 22:00", discharge: "2026-03-08 22:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 1380, roundedHours: 23, billableHours: 23, flags: [] });
});
test("AC-3: day when clocks go back (2026-11-01) bills 25 real hours, not 24", () => {
  const r = code.billableObservationHours({ admission: "2026-10-31 22:00", discharge: "2026-11-01 22:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 1500, roundedHours: 25, billableHours: 25, flags: [] });
});
test("AC-4: a 72 hour stay is capped and billed as 48 hours", () => {
  const r = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-13 08:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 4320, roundedHours: 72, billableHours: 48, flags: [] });
});
test("AC-5: ambiguous and nonexistent local times are flagged with no hours computed", () => {
  const a = code.billableObservationHours({ admission: "2026-11-01 01:30", discharge: "2026-11-01 05:00" });
  assert.equal(a.status, "ambiguous");
  assert.equal(a.elapsedMinutes, null);
  assert.equal(a.roundedHours, null);
  assert.equal(a.billableHours, null);
  assert.equal(a.flags.length, 1);
  assert.match(a.flags[0], /admission/);
  const n = code.billableObservationHours({ admission: "2026-03-08 00:00", discharge: "2026-03-08 02:30" });
  assert.equal(n.status, "nonexistent");
  assert.equal(n.elapsedMinutes, null);
  assert.equal(n.roundedHours, null);
  assert.equal(n.billableHours, null);
  assert.equal(n.flags.length, 1);
  assert.match(n.flags[0], /discharge/);
});
test("discharge before admission is flagged invalid and an unknown input field throws", () => {
  const r = code.billableObservationHours({ admission: "2026-01-10 10:00", discharge: "2026-01-10 08:00" });
  assert.equal(r.status, "invalid");
  assert.equal(r.elapsedMinutes, null);
  assert.equal(r.roundedHours, null);
  assert.equal(r.billableHours, null);
  assert.ok(r.flags.length >= 1);
  assert.match(r.flags[0], /discharge/);
