    const roundedHours = Math.ceil(elapsedMinutes / 60);
    const billableHours = Math.min(roundedHours, 48);
    return { status: "ok", elapsedMinutes, roundedHours, billableHours, flags: [] };
  }
  return { billableObservationHours };
})()
